    <div><label for="formato">Formato</label><select id="formato"><option value="vertical_recorte">Em pé, recortado na pessoa</option><option value="vertical_desfocado">Em pé, imagem inteira e fundo desfocado</option><option value="quadrado">Quadrado 1:1 (feed)</option></select></div>
