<script>
(function () {
  var PASSE = '__PASSE__', ORIGEM = '', MAX_MB = 1024;
  var el = function (s) { return document.querySelector(s); };
  function pronto(origem, texto, url) { ORIGEM = origem; el('#info').innerHTML = texto; el('#enviar').disabled = false; el('#erro').textContent = ''; if (url) { el('#previa').src = url; el('#previa').hidden = false; } }
  el('#exemplo').addEventListener('click', function () { pronto('exemplo-podcast', '✅ Vídeo de exemplo: <b>Papo de Negócio, ep. 12</b> (3 min 24 s, duas vozes falando de Instagram). O estúdio aparece sem ninguém, então a IA usa a imagem inteira em vez do recorte na pessoa.', '/videos/arquivo/exemplos/podcast.mp4'); });
  var drop = el('#drop'), inp = el('#arquivo');
  drop.addEventListener('click', function () { inp.click(); });
  drop.addEventListener('keydown', function (e) { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); inp.click(); } });
  ['dragover', 'dragenter'].forEach(function (t) { drop.addEventListener(t, function (e) { e.preventDefault(); drop.classList.add('on'); }); });
  ['dragleave', 'drop'].forEach(function (t) { drop.addEventListener(t, function (e) { e.preventDefault(); drop.classList.remove('on'); }); });
  drop.addEventListener('drop', function (e) { if (e.dataTransfer.files[0]) envia(e.dataTransfer.files[0]); });
  inp.addEventListener('change', function () { if (inp.files[0]) envia(inp.files[0]); });
  function envia(f) {
    if (f.size > MAX_MB * 1024 * 1024) { el('#info').textContent = '⚠️ Arquivo maior que 1 GB.'; return; }
    ORIGEM = ''; el('#enviar').disabled = true; el('#barra-wrap').hidden = false; el('#barra').style.width = '0'; el('#info').textContent = 'Enviando ' + f.name + '…';
    var fd = new FormData(); fd.append('arquivo', f);
    var x = new XMLHttpRequest(); x.open('POST', '/videos/enviar'); x.setRequestHeader('X-Passe', PASSE);
    x.upload.onprogress = function (e) { if (e.lengthComputable) { el('#barra').style.width = (e.loaded / e.total * 100) + '%'; el('#info').textContent = 'Enviando… ' + Math.round(e.loaded / e.total * 100) + '% (não feche a página)'; } };
    x.onload = function () {
      var r = {}; try { r = JSON.parse(x.responseText); } catch (e) {}
      if (x.status !== 200) { el('#info').textContent = '⚠️ ' + (r.detail || 'Não deu para enviar (erro ' + x.status + ').'); return; }
      if (!r.tem_video) { el('#info').textContent = '⚠️ Esse arquivo não tem imagem de vídeo.'; return; }
      if (!r.tem_audio) { el('#info').textContent = '⚠️ Esse vídeo não tem som: os cortes automáticos precisam de alguém falando.'; return; }
      var min = Math.floor(r.duracao / 60), seg = Math.round(r.duracao % 60);
      pronto(r.id, '✅ Enviado: ' + (min ? min + ' min ' : '') + seg + ' s, ' + r.largura + '×' + r.altura + (r.duracao < 90 ? '<br>⚠️ Vídeo curto: podem sair menos cortes do que o pedido.' : ''), URL.createObjectURL(f));
    };
    x.onerror = function () { el('#info').textContent = '⚠️ Falha de conexão no envio. Tente de novo.'; };
    x.send(fd);
  }
  el('#form').addEventListener('submit', function (e) {
    e.preventDefault(); el('#erro').textContent = '';
    if (!ORIGEM) { el('#erro').textContent = 'Envie um vídeo (ou use o de exemplo) antes de começar.'; return; }
    var d = { origem: ORIGEM };
    ['quantidade', 'tamanho', 'formato', 'foco', 'marca', 'cor', 'cta'].forEach(function (k) { d[k] = el('#' + k).value; });
    ['titulo', 'legendas'].forEach(function (k) { d[k] = el('#' + k).checked; });
    var bt = el('#enviar'); bt.disabled = true; bt.textContent = 'Começando…';
    fetch('cortes', { method: 'POST', headers: { 'Content-Type': 'text/plain' }, body: JSON.stringify(d) }).then(function (r) { return r.json(); }).then(function (r) {
      if (!r.ok) { el('#erro').textContent = (r.erros || ['Não deu para começar.']).join(' '); bt.disabled = false; bt.textContent = '✂️ Criar os cortes'; return; }
      location.href = r.link;
    }).catch(function () { el('#erro').textContent = 'Falha de conexão.'; bt.disabled = false; bt.textContent = '✂️ Criar os cortes'; });
  });
})();
</script></body></html>
";
return [{ json: { html: PAGINA.replace('__PASSE__', passe) } }];

// Confere o pedido e cria o código do trabalho. O vídeo já foi enviado direto para a oficina (fora do n8n).
let b = $('🔔 Pedido de cortes (POST)').first().json.body;
if (typeof b === 'string') { try { b = JSON.parse(b); } catch (e) { b = {}; } }
b = b || {};
const crypto = require('crypto');
const limpa = (v, max) => String(v ?? '').replace(/[\u0000-\u0008\u000b-\u001f\u007f<>{}\\]/g, ' ').replace(/\s+/g, ' ').trim().slice(0, max);
const TAMANHOS = { curto: { min: 15, max: 35, txt: '15 a 35 segundos' }, medio: { min: 30, max: 60, txt: '30 a 60 segundos' }, longo: { min: 55, max: 90, txt: '55 a 90 segundos' } };
const FOCOS = { auto: 'os momentos com mais chance de viralizar (qualquer tipo)', dicas: 'dicas práticas e ensinamentos', historias: 'histórias e casos contados', humor: 'momentos engraçados', polemica: 'opiniões fortes e polêmicas', emocao: 'momentos emocionantes e inspiradores' };
const FORMATOS = ['vertical_recorte', 'vertical_desfocado', 'quadrado'];
const origem = String(b.origem || '');
const erros = [];
if (!/^([a-f0-9]{12}\.[a-z0-9]{2,5}|exemplo-[a-z0-9]{3,30})$/.test(origem)) erros.push('Envie um vídeo (ou use o de exemplo) antes de começar.');
const op = {
  quantidade: [3, 5, 8].includes(Number(b.quantidade)) ? Number(b.quantidade) : 5,
  tamanho: TAMANHOS[b.tamanho] ? b.tamanho : 'medio',
  formato: FORMATOS.includes(b.formato) ? b.formato : 'vertical_recorte',
  foco: FOCOS[b.foco] ? b.foco : 'auto',
  titulo: b.titulo !== false, legendas: b.legendas !== false,
  cor: /^#[0-9a-fA-F]{6}$/.test(b.cor || '') ? String(b.cor).toUpperCase() : '#FFD400',
  marca: limpa(b.marca, 30), cta: limpa(b.cta, 40),
};
if (op.marca && !op.marca.startsWith('@') && /^[a-zA-Z0-9._]+$/.test(op.marca)) op.marca = '@' + op.marca;
const job = 'c' + Date.now().toString(36) + crypto.randomBytes(2).toString('hex');
const base = String($('🔔 Pedido de cortes (POST)').first().json.webhookUrl || '').split('/webhook/')[0];
return [{ json: { valido: erros.length === 0, erros, job, origem, op, tamanho: TAMANHOS[op.tamanho], foco_txt: FOCOS[op.foco], criado_em: Date.now(),
  link: `${base}/webhook/cortes-ver?job=${job}`, publico: `${base}/videos/arquivo`, chave_limite: '<SEGREDO_REMOVIDO>' + new Date().toISOString().slice(0, 13) } }];

// Organiza a transcrição: palavras com o tempo de cada uma e FRASES numeradas (a IA escolhe os cortes por número de frase, então o corte nunca começa nem termina no meio de uma frase).
let r = {}, rodou = false;
try { if ($('👂 Whisper: transcreve com o tempo de cada palavra').isExecuted) { rodou = true; r = $('👂 Whisper: transcreve com o tempo de cada palavra').first().json || {}; } } catch (e) {}
if (typeof r.data === 'string') { try { r = JSON.parse(r.data); } catch (e) {} }
const v = $('🧩 Confere o pedido').first().json;
const palavras = (Array.isArray(r.words) ? r.words : []).map(p => ({ w: String(p.word || '').trim(), s: Number(p.start) || 0, e: Number(p.end) || 0 })).filter(p => p.w);
const frases = [];
let atual = [];
const fecha = () => { if (atual.length) { frases.push({ i: frases.length, s: atual[0].s, e: atual[atual.length - 1].e, ini: atual[0].k, fim: atual[atual.length - 1].k, texto: atual.map(x => x.w).join(' ') }); atual = []; } };
palavras.forEach((p, k) => {
  const pausa = atual.length && p.s - atual[atual.length - 1].e > 1.2;
  if (pausa || atual.length >= 32) fecha();
  atual.push({ ...p, k });
  if (/[.!?…]$/.test(p.w)) fecha();
});
fecha();
const mmss = t => `${Math.floor(t / 60)}:${String(Math.floor(t % 60)).padStart(2, '0')}`;
let texto = frases.map(f => `#${f.i} [${mmss(f.s)}] ${f.texto}`).join('\n');
if (texto.length > 120000) texto = texto.slice(0, 120000) + '\n[... transcrição cortada por ser muito longa]';
const duracao = palavras.length ? palavras[palavras.length - 1].e : 0;
const tem_fala = frases.length >= 3;
const falhaWhisper = rodou && !palavras.length && r.error;
const erro = tem_fala ? '' : falhaWhisper ? 'A transcrição falhou (Whisper): ' + String((r.error && r.error.message) || r.error).slice(0, 160) + '. Tente de novo.'
  : 'Não achei fala neste vídeo: os cortes automáticos precisam de alguém falando.';
const texto_cacador = `VÍDEO: ${mmss(duracao)} de fala · ${frases.length} frases · idioma ${r.language || '?'}
QUERO: ${v.op.quantidade} cortes de ${v.tamanho.txt} cada, focando em ${v.foco_txt}.
Para cada corte devolva frase_inicio e frase_fim (os números #) — o corte vai do começo da primeira até o fim da última.
Me dê ${Math.min(16, v.op.quantidade * 2)} candidatos, sem se sobrepor, do melhor para o pior.

TRANSCRIÇÃO (#número [minuto:segundo] frase):
${texto}`;
return [{ json: { tem_fala, erro, idioma: r.language || '', duracao_fala: duracao, palavras, frases, texto_cacador } }];

function parseJSON(txt) {
  const s = String(txt || '').replace(/^\s*```(?:json)?\s*/i, '').replace(/```\s*$/i, '').trim();
  try { return JSON.parse(s); } catch (e) {}
  const a = s.indexOf('{'), b = s.lastIndexOf('}');
  if (a > -1 && b > a) { try { return JSON.parse(s.slice(a, b + 1)); } catch (e) {} }
  return null;
}

// Confere os cortes da caçadora: encaixa nas frases, respeita o tamanho pedido, tira sobreposição e prepara o pedido da revisora.
const v = $('🧩 Confere o pedido').first().json;
const t = $('🧩 Organiza a transcrição').first().json;
let j = null, respondeu = false;
try { const o = $('🤖 Caçadora de momentos').first().json.output; respondeu = !!o; j = parseJSON(o); } catch (e) {}
const F = t.frases, n = F.length;
const { min, max } = v.tamanho;
const dur = (a, b) => F[b].e - F[a].s;
const cand = (j && Array.isArray(j.cortes) ? j.cortes : []).map((c, k) => {
  let a = parseInt(c.frase_inicio, 10), b = parseInt(c.frase_fim, 10);
  if (!Number.isFinite(a) || !Number.isFinite(b) || !n) return null;
  a = Math.max(0, Math.min(n - 1, a)); b = Math.max(0, Math.min(n - 1, b));
  if (b < a) [a, b] = [b, a];
  while (dur(a, b) < min && b < n - 1) b++;   // curto demais: estica pelas frases seguintes
  while (dur(a, b) < min && a > 0) a--;       // ainda curto: puxa frases de antes
  while (dur(a, b) > max && b > a) b--;       // longo demais: tira frases do fim
  return { k, a, b, nota: Math.max(0, Math.min(100, Number(c.nota_viral) || 50)), tipo: String(c.tipo || '').slice(0, 30),
    motivo: String(c.motivo || '').slice(0, 220), titulo_sugerido: String(c.titulo || '').slice(0, 60) };
}).filter(c => c && dur(c.a, c.b) >= Math.min(min, 8));
cand.sort((x, y) => y.nota - x.nota);
const escolhidos = [];
for (const c of cand) if (!escolhidos.some(e => c.a <= e.b && e.a <= c.b)) escolhidos.push(c);
// a revisora recebe uns a mais que o pedido, para poder recusar os fracos
const lista = escolhidos.slice(0, Math.min(12, v.op.quantidade + 3));
if (!lista.length) {
  return [{ json: { ok: false, erro: !respondeu ? 'A IA caçadora não respondeu agora. Tente de novo em alguns minutos.'
    : !j ? 'A IA caçadora devolveu uma resposta que não deu para ler. Tente de novo.'
    : 'A IA não achou cortes bons neste vídeo. Tente outro foco ou outro tamanho.' } }];
}
const mmss = s => `${Math.floor(s / 60)}:${String(Math.floor(s % 60)).padStart(2, '0')}`;
const fr = f => `#${f.i} (${f.s.toFixed(1)}–${f.e.toFixed(1)} s) ${f.texto}`;
const texto_revisora = `TAMANHO PEDIDO: ${v.tamanho.txt} (do começo da 1ª frase ao fim da última; os segundos de cada frase estão entre parênteses) · FOCO: ${v.foco_txt} · QUERO NO FINAL: ${v.op.quantidade} cortes
Para cada candidato você vê 2 frases ANTES (contexto), as frases DO CORTE e 2 frases DEPOIS.

${lista.map((c, i) => `=== CANDIDATO ${i + 1} (id ${i + 1}) · ${mmss(F[c.a].s)}–${mmss(F[c.b].e)} · ${Math.round(dur(c.a, c.b))} s · nota da caçadora ${c.nota} · ${c.tipo}
ANTES: ${F.slice(Math.max(0, c.a - 2), c.a).map(fr).join(' ') || '(início do vídeo)'}
CORTE: ${F.slice(c.a, c.b + 1).map(fr).join(' ')}
DEPOIS: ${F.slice(c.b + 1, c.b + 3).map(fr).join(' ') || '(fim do vídeo)'}`).join('\n\n')}`;
