// Aplica a revisão: ajusta começo/fim (até 2 frases), tira os reprovados e fica com a quantidade pedida, do melhor para o pior.
const v = $('🧩 Confere o pedido').first().json;
const t = $('🧩 Organiza a transcrição').first().json;
const cc = $('🧩 Confere os cortes').first().json;
let r = null;
try { r = parseJSON($('🤖 Revisora de cortes').first().json.output); } catch (e) {}
const F = t.frases, n = F.length;
const { min, max } = v.tamanho;
const dur = (a, b) => F[b].e - F[a].s;
const rev = r && Array.isArray(r.cortes) ? r.cortes : [];
const num = (v, ref) => { const k = parseInt(v, 10); return Number.isFinite(k) ? k : ref; };
const perto = (v, ref) => v >= 0 && v < n && Math.abs(v - ref) <= 2;
const lista = cc.candidatos.map(c => {
  const x = rev.find(y => Number(y.id) === c.id) || {};
  let a = c.a, b = c.b;
  const na = num(x.frase_inicio, c.a), nb = num(x.frase_fim, c.b);
  // o ajuste vale inteiro ou não vale: aplicar só o começo ou só o fim cria um corte que nenhuma das duas escolheu
