if (aprovados.length < Math.min(2, semSobrepor.length)) aprovados = semSobrepor.slice(0, Math.min(2, semSobrepor.length));
const cortes = aprovados.slice(0, v.op.quantidade).map((c, i) => ({
  n: i + 1, a: c.a, b: c.b, inicio: Math.max(0, F[c.a].s - 0.12), fim: F[c.b].e + 0.35, nota: c.nota, tipo: c.tipo, motivo: c.motivo,
  ajustou: c.ajustou, titulo_sugerido: c.titulo_sugerido, texto: F.slice(c.a, c.b + 1).map(f => f.texto).join(' '),
