return [{ json: { cortes, recusados: semSobrepor.length - aprovados.length, revisou: !!r, tempos: cortes.map(c => Math.round((c.inicio + c.fim) / 2 * 100) / 100) } }];

// Monta o pedido para a IA com visão: 1 quadro do meio de cada corte, para achar quem fala e decidir se dá para recortar em pé em volta da pessoa.
const q = $('🛠️ Oficina: tira um quadro de cada corte').first().json.quadros || [];
const conteudo = [{ type: 'text', text: `São ${q.length} quadros de um vídeo, um do meio de cada corte (corte 1, 2, 3...). Cada corte vai virar um vídeo EM PÉ (9:16): ou recortamos uma faixa em pé (cerca de 1/3 da largura) em volta da pessoa, ou mostramos a imagem inteira com fundo desfocado. Para cada quadro diga:
- pessoa: true se aparece alguém falando ou em destaque
- x: posição horizontal do ROSTO de quem parece estar falando, de 0 (esquerda) a 1 (direita); sem pessoa = 0.5
- recortar: true se a faixa em pé em volta desse rosto mostra o que importa; false se o quadro tem 2 ou mais pessoas importantes afastadas, tela de computador, slide, gráfico, texto ou nome escrito importante, ou nenhuma pessoa (aí vai a imagem inteira)
- tela: true se o quadro é principalmente tela, slide, texto ou gráfico
RETORNE SOMENTE JSON: {"quadros":[{"corte":1,"pessoa":true,"x":0.5,"recortar":true,"tela":false}]}` }];
q.forEach((f, i) => {
  conteudo.push({ type: 'text', text: `CORTE ${i + 1}` });
  conteudo.push({ type: 'image_url', image_url: { url: 'data:image/jpeg;base64,' + f.b64 } });
