// Lê onde está a pessoa em cada corte (para o recorte em pé não cortar o rosto) e prepara o pedido da copywriter.
const v = $('🧩 Confere o pedido').first().json;
const t = $('🧩 Organiza a transcrição').first().json;
const ap = $('🧩 Aplica a revisão dos cortes').first().json;
let lidos = [];
try {
  const r = $('👀 IA acha a pessoa').first().json;
  const j = parseJSON(r.choices ? r.choices[0].message.content : '');
