  const x = Number(q.x), pessoa = q.pessoa === true, tela = q.tela === true;
  // sem resposta da visão: recorta no centro (o mais comum em podcast); com resposta: imagem inteira quando ela disser que não dá para recortar
  const recortar = typeof q.recortar === 'boolean' ? q.recortar : (pessoa && !tela);
