  const a = cp.textos.find(y => Number(y.n) === x.n) || {}, b = revisados.find(y => Number(y.n) === x.n) || {};
  const campo = k => (b[k] && (!Array.isArray(b[k]) || b[k].length)) ? b[k] : a[k];
