  const q = lidos.find(x => Number(x.corte) === i + 1) || lidos[i] || {};
  const x = Number(q.x), pessoa = q.pessoa === true, tela = q.tela === true;
  // sem resposta da visão: recorta no centro (o mais comum em podcast); com resposta: imagem inteira quando ela disser que não dá para recortar
  const recortar = typeof q.recortar === 'boolean' ? q.recortar : (pessoa && !tela);
  return { ...c, foco_x: Number.isFinite(x) ? Math.min(1, Math.max(0, x)) : 0.5, pessoa, tela, desfocar: lidos.length > 0 && !recortar };
});
const texto_copy = `IDIOMA DO VÍDEO: ${t.idioma || 'o mesmo da fala'} (escreva neste idioma)
CRIADOR: ${v.op.marca || '-'}

CORTES:
${cortes.map(c => `=== CORTE ${c.n} (${c.tipo || 'corte'}) — por que é bom: ${c.motivo || '-'}
FALA: ${c.texto}`).join('\n\n')}`;
return [{ json: { cortes, viu: lidos.length > 0, inteiros: cortes.filter(c => c.desfocar).length, texto_copy } }];

function parseJSON(txt) {
  const s = String(txt || '').replace(/^\s*```(?:json)?\s*/i, '').replace(/```\s*$/i, '').trim();
  try { return JSON.parse(s); } catch (e) {}
  const a = s.indexOf('{'), b = s.lastIndexOf('}');
  if (a > -1 && b > a) { try { return JSON.parse(s.slice(a, b + 1)); } catch (e) {} }
  return null;
}

// Lê os títulos e legendas da copywriter e prepara a revisora dos textos (ela confere tudo contra a fala de cada corte).
const v = $('🧩 Confere o pedido').first().json;
const t = $('🧩 Organiza a transcrição').first().json;
const en = $('🧩 Lê o enquadramento').first().json;
let c = null;
try { c = parseJSON($('🤖 Copywriter dos cortes').first().json.output); } catch (e) {}
const textos = c && Array.isArray(c.cortes) ? c.cortes : [];
const texto_revisora = `IDIOMA DO VÍDEO: ${t.idioma || 'o mesmo da fala'}
CRIADOR (@): ${v.op.marca || 'não informado'}

${en.cortes.map(x => {
  const k = textos.find(y => Number(y.n) === x.n) || {};
  return `=== CORTE ${x.n}
FALA: ${x.texto}
TEXTOS DA COPYWRITER: ${JSON.stringify({ titulo_tela: k.titulo_tela || '', titulo_post: k.titulo_post || '', legenda: k.legenda || '', hashtags: Array.isArray(k.hashtags) ? k.hashtags : [] })}`;
}).join('\n\n')}`;
return [{ json: { textos, copy_ia: textos.length > 0, texto_revisora } }];

function parseJSON(txt) {
  const s = String(txt || '').replace(/^\s*```(?:json)?\s*/i, '').replace(/```\s*$/i, '').trim();
  try { return JSON.parse(s); } catch (e) {}
  const a = s.indexOf('{'), b = s.lastIndexOf('}');
  if (a > -1 && b > a) { try { return JSON.parse(s.slice(a, b + 1)); } catch (e) {} }
  return null;
}

// Junta cortes + enquadramento + textos revisados e monta o pedido para a oficina (com as palavras de cada corte para a legenda acender junto com a fala).
const v = $('🧩 Confere o pedido').first().json;
const t = $('🧩 Organiza a transcrição').first().json;
const en = $('🧩 Lê o enquadramento').first().json;
const cp = $('🧩 Lê os textos da copywriter').first().json;
let rv = null;
try { rv = parseJSON($('🤖 Revisora dos textos').first().json.output); } catch (e) {}
const revisados = rv && Array.isArray(rv.cortes) ? rv.cortes : [];
const limpa = (s, m) => String(s || '').replace(/[<>{}\\]/g, '').trim().slice(0, m);
const semEmoji = s => String(s || '').replace(/[\u{1F000}-\u{1FAFF}\u{2600}-\u{27BF}\u{FE0F}\u{200D}]/gu, '').replace(/\s+/g, ' ').trim();
const cortes = en.cortes.map(x => {
  // campo a campo: o revisado vale; se a revisora deixou vazio, fica o da copywriter
  const a = cp.textos.find(y => Number(y.n) === x.n) || {}, b = revisados.find(y => Number(y.n) === x.n) || {};
  const campo = k => (b[k] && (!Array.isArray(b[k]) || b[k].length)) ? b[k] : a[k];
  const palavras = t.palavras.slice(t.frases[x.a].ini, t.frases[x.b].fim + 1).map(p => ({ w: p.w, s: p.s, e: p.e }));
  return { ...x, titulo_tela: v.op.titulo ? semEmoji(limpa(campo('titulo_tela') || x.titulo_sugerido, 60)) : '',
    titulo_post: limpa(campo('titulo_post'), 100), legenda: limpa(campo('legenda'), 1200),
    // sem acento: #negociosonline é a hashtag que as pessoas digitam e buscam (#negóciosonline é outra, quase vazia)
    hashtags: [...new Set((Array.isArray(campo('hashtags')) ? campo('hashtags') : []).map(h => String(h).normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/[#\s]/g, '').toLowerCase()))].filter(Boolean).slice(0, 12),
    formato: x.desfocar ? 'vertical_desfocado' : '', palavras };
});
return [{ json: { cortes, copy_ia: cp.copy_ia, textos_revisados: !!rv,
  problemas_textos: rv && Array.isArray(rv.problemas) ? rv.problemas.map(p => String(p).slice(0, 240)).slice(0, 12) : [],
  corpo: JSON.stringify({ job: v.job, origem: v.origem, formato: v.op.formato,
    cortes: cortes.map(x => ({ n: x.n, inicio: x.inicio, fim: x.fim, foco_x: x.foco_x, formato: x.formato, titulo_tela: x.titulo_tela, palavras: x.palavras })),
    opcoes: { cor: v.op.cor, marca: v.op.marca, cta: v.op.cta, legendas: v.op.legendas } }) } }];

// Lê o andamento dos cortes na oficina e decide se o laço continua.
const st = $input.first().json || {};
const v = $('🧩 Confere o pedido').first().json;
const estado = st.estado || 'desconhecido';
const status = { job: v.job, etapa: 'cortando', progresso: Number(st.progresso) || 0, detalhe: `✂️ ${st.etapa || 'cortando'} · ${Number(st.progresso) || 0}%`, op: v.op };
return [{ json: { ...st, estado, terminou: estado !== 'montando', status: JSON.stringify(status) } }];

// Grava o resultado: cada corte com vídeo, capa, nota, motivo, tempo no original e textos para postar, mais o ZIP com todos.
const v = $('🧩 Confere o pedido').first().json;
const st = $('🧩 Atualiza o andamento').item.json;
const ju = $('🧩 Junta tudo').first().json;
const ap = $('🧩 Aplica a revisão dos cortes').first().json;
const tr = $('🧩 Organiza a transcrição').first().json;
if (st.estado !== 'pronto') {
  return [{ json: { status: JSON.stringify({ job: v.job, etapa: 'erro', op: v.op,
    erro: st.estado === 'erro' ? 'O corte falhou: ' + String(st.erro || '').slice(-220) : 'A oficina perdeu este trabalho (reiniciou?). Tente de novo.' }) } }];
}
const pub = v.publico;
const prontos = st.cortes || [];
const cortes = ju.cortes.map((c, i) => {
  const p = prontos.find(x => Number(x.n) === c.n) || prontos[i] || {};
  return { n: c.n, video: p.video ? `${pub}/${p.video}` : '', capa: p.capa ? `${pub}/${p.capa}` : '', duracao: p.duracao, tamanho_mb: p.tamanho_mb,
    inicio: c.inicio, fim: c.fim, nota: c.nota, tipo: c.tipo, motivo: c.motivo, ajustou: c.ajustou, titulo_tela: c.titulo_tela,
    titulo_post: c.titulo_post, legenda: c.legenda, hashtags: c.hashtags, texto: String(c.texto || '').slice(0, 700),
    pessoa: c.pessoa, tela: c.tela, inteiro: c.formato === 'vertical_desfocado' };
});
return [{ json: { status: JSON.stringify({ job: v.job, etapa: 'pronto', op: v.op, cortes, zip: st.zip ? `${pub}/${st.zip}` : '', zip_mb: st.zip_mb,
  recusados: ap.recusados, revisou: ap.revisou, copy_ia: ju.copy_ia, textos_revisados: ju.textos_revisados, problemas_textos: ju.problemas_textos,
  idioma: tr.idioma, duracao_fala: Math.round(tr.duracao_fala), segundos: Math.round((Date.now() - v.criado_em) / 1000) }) } }];

// O cortador respondeu na hora com o link da página de andamento.
const r = $input.first().json;
if (!r.ok) throw new Error('O cortador recusou o teste: ' + (r.erros || [r.message || 'sem resposta']).join(' '));
return [{ json: { '👉 abra para ver ao vivo': r.link, job: String(r.link).split('job=')[1] } }];

// pronto = mostra os cortes · erro = o node fica vermelho com o motivo
const s = $input.first().json;
const n = (s.cortes || []).length;
if (s.etapa === 'pronto') return [{ json: { '✅': n + (n === 1 ? ' corte pronto' : ' cortes prontos') + ' em ' + s.segundos + ' s', '📦 todos (ZIP)': s.zip,
  '✂️ cortes': (s.cortes || []).map(c => c.n + '. nota ' + Math.round(c.nota) + ' · ' + Math.round(c.duracao) + ' s · ' + (c.titulo_tela || c.titulo_post || '') + ' → ' + c.video),
  '🔍 a revisora recusou': s.recusados || 0, '✍️ textos corrigidos': (s.problemas_textos || []).join(' | ') || 'nada', '👂 fala analisada (s)': s.duracao_fala, idioma: s.idioma } }];
if (s.etapa === 'erro') throw new Error('O cortador parou com erro: ' + s.erro);
throw new Error('Passou de 15 minutos sem terminar (última etapa: ' + (s.etapa || '?') + '). Veja na aba Executions.');
